void main() => runApp(const NovaApp());
const courses = ['مبادئ المحاسبة المالية','مبادئ الاقتصاد','مبادئ الإدارة','لغة إنجليزية للمتخصصين','رياضيات تحليل الأعمال التجارية','التفكير الابتكاري','إدارة رياضية'];

class CourseData {
  String source='', notes='', laws='', keywords='', terms='', questions='';
  Map<String,dynamic> toJson()=>{'source':source,'notes':notes,'laws':laws,'keywords':keywords,'terms':terms,'questions':questions};
  void fromJson(Map<String,dynamic> j){source=j['source']??'';notes=j['notes']??'';laws=j['laws']??'';keywords=j['keywords']??'';terms=j['terms']??'';questions=j['questions']??'';}
}
class Store extends ChangeNotifier {
  final data={for(final c in courses)c:CourseData()};
  Future<void> load() async {final p=await SharedPreferences.getInstance();for(final c in courses){final s=p.getString(c);if(s!=null){try{data[c]!.fromJson(jsonDecode(s));}catch(_){}}}notifyListeners();}
  Future<void> save(String c) async {final p=await SharedPreferences.getInstance();await p.setString(c,jsonEncode(data[c]!.toJson()));notifyListeners();}
}
class NovaApp extends StatefulWidget {const NovaApp({super.key});@override State<NovaApp> createState()=>_NovaAppState();}
class _NovaAppState extends State<NovaApp>{final store=Store();@override void initState(){super.initState();store.load();} @override Widget build(BuildContext context)=>AnimatedBuilder(animation:store,builder:(_,__)=>MaterialApp(debugShowCheckedModeBanner:false,title:'NOVA Study',theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xff557dff),brightness:Brightness.dark),scaffoldBackgroundColor:const Color(0xff0c1222),cardTheme:const CardThemeData(color:Color(0xff18223a))),home:MainPage(store:store)));}
class MainPage extends StatefulWidget{final Store store;const MainPage({super.key,required this.store});@override State<MainPage> createState()=>_MainPageState();}
class _MainPageState extends State<MainPage>{int tab=0;String course=courses[0];@override Widget build(BuildContext context){final pages=[home(),StudyPage(store:widget.store,course:course,onCourse:(v)=>setState(()=>course=v)),ExamPage(store:widget.store,course:course,onCourse:(v)=>setState(()=>course=v)),TermsPage(store:widget.store,course:course,onCourse:(v)=>setState(()=>course=v))];return Scaffold(appBar:AppBar(title:const Text('NOVA Study')),body:pages[tab],bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const[NavigationDestination(icon:Icon(Icons.home),label:'الرئيسية'),NavigationDestination(icon:Icon(Icons.menu_book),label:'المذاكرة'),NavigationDestination(icon:Icon(Icons.quiz),label:'الامتحان'),NavigationDestination(icon:Icon(Icons.translate),label:'المصطلحات')]));}
Widget home()=>ListView(padding:const EdgeInsets.all(16),children:[Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xff214a91),Color(0xff653c9c)]),borderRadius:BorderRadius.circular(22)),child:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(Icons.auto_awesome,size:36),SizedBox(height:8),Text('ذاكر بذكاء مع NOVA',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),Text('نظّم محاضراتك وملخصاتك وأسئلتك بدون API أو اشتراك.') ])),const SizedBox(height:14),for(int i=0;i<courses.length;i++)Card(child:ListTile(leading:CircleAvatar(child:Text('${i+1}')),title:Text(courses[i]),subtitle:Text(widget.store.data[courses[i]]!.source.isEmpty?'أضف ملف المحاضرة من شاشة المذاكرة':'تم حفظ نص المحاضرة'),trailing:const Icon(Icons.chevron_right),onTap:()=>setState((){course=courses[i];tab=1;}))),const Text('تنبيه: التطبيق يستخرج النص من PDF النصي، لكنه لا يكتب شرحًا أو أسئلة دقيقة تلقائيًا دون محتوى مجهز مسبقًا.')]);}}
class StudyPage extends StatefulWidget{final Store store;final String course;final ValueChanged<String> onCourse;const StudyPage({super.key,required this.store,required this.course,required this.onCourse});@override State<StudyPage> createState()=>_StudyPageState();}
class _StudyPageState extends State<StudyPage>{String? initialized;late TextEditingController notes,laws,keywords,terms,questions;void setup(){final d=widget.store.data[widget.course]!;notes=TextEditingController(text:d.notes);laws=TextEditingController(text:d.laws);keywords=TextEditingController(text:d.keywords);terms=TextEditingController(text:d.terms);questions=TextEditingController(text:d.questions);initialized=widget.course;}@override void didUpdateWidget(covariant StudyPage old){super.didUpdateWidget(old);if(old.course!=widget.course)initialized=null;}@override void dispose(){if(initialized!=null){notes.dispose();laws.dispose();keywords.dispose();terms.dispose();questions.dispose();}super.dispose();}
Future<void> importPdf()async{try{final r=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['pdf'],withData:true);if(r==null)return;final f=r.files.single;final b=f.bytes??(f.path!=null?await File(f.path!).readAsBytes():null);if(b==null)throw Exception('تعذر قراءة الملف');final doc=PdfDocument(inputBytes:b);final t=PdfTextExtractor(doc).extractText();doc.dispose();widget.store.data[widget.course]!.source=t;await widget.store.save(widget.course);if(mounted)showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('تم استخراج النص'),content:SizedBox(width:400,child:SingleChildScrollView(child:SelectableText(t.isEmpty?'لم يتم العثور على نص. ربما الملف عبارة عن صور.':'تم استخراج ${t.length} حرفًا من ${f.name}\n\n'+t))),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('إغلاق'))]));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('خطأ: $e')));}}
Future<void> save()async{final d=widget.store.data[widget.course]!;d.notes=notes.text;d.laws=laws.text;d.keywords=keywords.text;d.terms=terms.text;d.questions=questions.text;await widget.store.save(widget.course);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم الحفظ على الجهاز')));}
Future<void> export()async{await save();final d=widget.store.data[widget.course]!;final font=await PdfGoogleFonts.notoNaskhArabicRegular();final bold=await PdfGoogleFonts.notoNaskhArabicBold();final pdf=pw.Document();pw.Widget sec(String title,String body)=>pw.Column(crossAxisAlignment:pw.CrossAxisAlignment.stretch,children:[pw.Container(color:PdfColor.fromHex('#DCE8FF'),padding:const pw.EdgeInsets.all(8),child:pw.Text(title,textDirection:pw.TextDirection.rtl,style:pw.TextStyle(font:bold,fontSize:16,color:PdfColor.fromHex('#183A75'))),),pw.SizedBox(height:6),pw.Text(body.isEmpty?'لم تتم إضافة محتوى بعد.':body,textDirection:pw.TextDirection.rtl,style:pw.TextStyle(font:font,fontSize:11)),pw.SizedBox(height:14)]);pdf.addPage(pw.MultiPage(theme:pw.ThemeData.withFont(base:font,bold:bold),build:(_)=>[pw.Text('NOVA Study',style:pw.TextStyle(font:bold,fontSize:24)),pw.Text(widget.course,textDirection:pw.TextDirection.rtl,style:pw.TextStyle(font:bold,fontSize:18)),sec('الشرح المبسط',d.notes),sec('القوانين والمعادلات',d.laws),sec('الكلمات المفتاحية',d.keywords),sec('المصطلحات',d.terms),sec('بنك الأسئلة',d.questions)]));await Printing.layoutPdf(onLayout:(_)=>pdf.save(),name:'NOVA_Study.pdf');}
Widget field(String label,TextEditingController c,String hint)=>Padding(padding:const EdgeInsets.only(bottom:12),child:TextField(controller:c,minLines:3,maxLines:10,decoration:InputDecoration(labelText:label,hintText:hint,alignLabelWithHint:true,border:const OutlineInputBorder())));
@override Widget build(BuildContext context){if(initialized!=widget.course)setup();final d=widget.store.data[widget.course]!;return ListView(padding:const EdgeInsets.all(14),children:[DropdownButtonFormField<String>(value:widget.course,isExpanded:true,decoration:const InputDecoration(labelText:'المادة',border:OutlineInputBorder()),items:courses.map((c)=>DropdownMenuItem(value:c,child:Text(c))).toList(),onChanged:(v){if(v!=null)widget.onCourse(v);}),const SizedBox(height:10),FilledButton.icon(onPressed:importPdf,icon:const Icon(Icons.picture_as_pdf),label:const Text('اختيار ملف PDF')),ExpansionTile(title:const Text('النص المستخرج من المحاضرة'),children:[Padding(padding:const EdgeInsets.all(10),child:SelectableText(d.source.isEmpty?'لم يتم استيراد ملف.':d.source)),TextButton(onPressed:()=>notes.text='${notes.text}\n\n${d.source}',child:const Text('نسخ النص إلى الشرح لتعديله'))]),field('الشرح المبسط عربي + English',notes,'أدخل الشرح الذي تريد مذاكرته'),field('القوانين والمعادلات',laws,'كل قانون في سطر مع شرح الرموز'),field('الكلمات المفتاحية',keywords,'الكلمة وتعريفها المختصر'),field('المصطلحات',terms,'كل سطر: English term | المعنى بالعربي'),field('أسئلة الاختيار من متعدد',questions,'كل سطر: السؤال | أ | ب | ج | د | رقم الإجابة 1-4 | تفسير الإجابة'),FilledButton.icon(onPressed:save,icon:const Icon(Icons.save),label:const Text('حفظ المادة')),const SizedBox(height:8),OutlinedButton.icon(onPressed:export,icon:const Icon(Icons.picture_as_pdf_outlined),label:const Text('تصدير مذكرة PDF'))]);}}
class ExamPage extends StatefulWidget{final Store store;final String course;final ValueChanged<String> onCourse;const ExamPage({super.key,required this.store,required this.course,required this.onCourse});@override State<ExamPage> createState()=>_ExamPageState();}
class _ExamPageState extends State<ExamPage>{final answers=<int,int>{};bool submitted=false;List<List<String>> parse(String s)=>s.split('\n').map((x)=>x.split('|').map((y)=>y.trim()).toList()).where((x)=>x.length>=7&&x[0].isNotEmpty).toList();@override Widget build(BuildContext context){final rows=parse(widget.store.data[widget.course]!.questions);int score=0;for(int i=0;i<rows.length;i++){if(answers[i]==(int.tryParse(rows[i][5])??0))score++;}return ListView(padding:const EdgeInsets.all(12),children:[DropdownButtonFormField<String>(value:widget.course,isExpanded:true,decoration:const InputDecoration(labelText:'المادة',border:OutlineInputBorder()),items:courses.map((c)=>DropdownMenuItem(value:c,child:Text(c))).toList(),onChanged:(v){if(v!=null)setState((){widget.onCourse(v);answers.clear();submitted=false;});}),if(rows.isEmpty)const Padding(padding:EdgeInsets.all(20),child:Text('أضف أسئلة في شاشة المذاكرة أولًا.')),if(submitted)Text('النتيجة: $score / ${rows.length}',style:const TextStyle(fontSize:24,fontWeight:FontWeight.bold)),for(int i=0;i<rows.length;i++)Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${i+1}. ${rows[i][0]}',style:const TextStyle(fontWeight:FontWeight.bold)),for(int j=1;j<=4;j++)RadioListTile<int>(contentPadding:EdgeInsets.zero,dense:true,value:j,groupValue:answers[i],title:Text(rows[i][j]),onChanged:submitted?null:(v)=>setState(()=>answers[i]=v!)),if(submitted)Text('الإجابة: ${rows[i][(int.tryParse(rows[i][5])??1).clamp(1,4)]}\nالشرح: ${rows[i][6]}',style:const TextStyle(color:Colors.lightGreenAccent))]))),if(rows.isNotEmpty)FilledButton(onPressed:()=>setState(()=>submitted=true),child:const Text('تصحيح الامتحان')),if(submitted)TextButton(onPressed:()=>setState((){answers.clear();submitted=false;}),child:const Text('إعادة الامتحان'))]);}}
class TermsPage extends StatefulWidget{final Store store;final String course;final ValueChanged<String> onCourse;const TermsPage({super.key,required this.store,required this.course,required this.onCourse});@override State<TermsPage> createState()=>_TermsPageState();}
class _TermsPageState extends State<TermsPage>{final q=TextEditingController();@override void dispose(){q.dispose();super.dispose();}@override Widget build(BuildContext context){final rows=widget.store.data[widget.course]!.terms.split('\n').map((s)=>s.split('|').map((x)=>x.trim()).toList()).where((r)=>r.length>=2&&('${r[0]} ${r[1]}').toLowerCase().contains(q.text.toLowerCase())).toList();return Column(children:[Padding(padding:const EdgeInsets.all(12),child:DropdownButtonFormField<String>(value:widget.course,isExpanded:true,decoration:const InputDecoration(labelText:'المادة',border:OutlineInputBorder()),items:courses.map((c)=>DropdownMenuItem(value:c,child:Text(c))).toList(),onChanged:(v){if(v!=null)widget.onCourse(v);})),Padding(padding:const EdgeInsets.symmetric(horizontal:12),child:TextField(controller:q,onChanged:(_)=>setState((){}),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'ابحث عن مصطلح',border:OutlineInputBorder()))),Expanded(child:rows.isEmpty?const Center(child:Text('أضف المصطلحات في شاشة المذاكرة.')):ListView(children:[for(final r in rows)Card(child:ListTile(leading:const Icon(Icons.translate),title:Text(r[0]),subtitle:Text(r[1])))]))]);}}